// Original native contour study. This recipe uses actual Rive contour types;
// the gallery's editable source is generated by importing these records.
export function tideRecords() {
 const ink=0xff284f4b,mint=0xffa5d9c9,pale=0xffd8eee0,cream=0xfffffbef,peach=0xffe8b394;
 const root=[],group=(name,x,y)=>{const n={name,type:'Node',fields:{x,y},children:[]};root.push(n);return n.children;};
 const add=(parent,name,type,fields,fill,vertices=[],stroke)=>{parent.push({name,type:'Shape',fields:{},contour:{type,fields},fill,vertices,stroke});};
 const ellipse=(parent,name,x,y,w,h,fill,stroke)=>add(parent,name,'Ellipse',{x,y,width:w,height:h},fill,[],stroke);
 const straight=(x,y)=>({type:'StraightVertex',fields:{x,y}});
 const mirror=(x,y,rotation,distance)=>({type:'CubicMirroredVertex',fields:{x,y,rotation,distance}});
 const asym=(x,y,rotation,inDistance,outDistance)=>({type:'CubicAsymmetricVertex',fields:{x,y,rotation,inDistance,outDistance}});
 const path=(parent,name,vertices,fill,stroke,closed=true)=>add(parent,name,'PointsPath',{isClosed:closed},fill,vertices,stroke);
 add(root,'shore paper','Rectangle',{width:512,height:512,x:256,y:256},cream);
 ellipse(root,'sea glass sky',256,232,414,392,0xffdcece3);
 ellipse(root,'setting sun',357,133,76,76,peach);
 ellipse(root,'sun shimmer',349,125,48,48,0xfff1c9a8);
 path(root,'far tide',[straight(50,335),asym(153,319,0,61,56),asym(338,331,0,74,65),straight(462,319),straight(462,443),straight(50,443)],0xffb7d3cd);
 path(root,'near tide',[straight(25,390),asym(162,373,0,70,65),asym(336,387,0,67,57),straight(487,366),straight(487,488),straight(25,488)],0xff8ebeb7);
 ellipse(root,'resting stone',255,418,245,57,0xff648d87);
 ellipse(root,'stone light',246,409,228,45,0xff98b1a2);
 const seal=group('Pebble',251,282);
 path(seal,'left flipper',[asym(-64,31,2.4,18,37),asym(-112,81,2.4,28,16),asym(-115,96,-2.1,12,13),asym(-49,69,-.7,31,22)],mint,{color:ink,width:4});
 path(seal,'tail fan',[straight(39,103),asym(100,105,-.4,24,23),asym(117,119,1.2,13,12),asym(88,133,2.9,22,14),straight(38,128)],mint,{color:ink,width:4});
 path(seal,'soft silhouette',[asym(-83,85,-1.8,30,52),asym(-62,-64,-1.12,50,35),mirror(-4,-113,.08,37),asym(61,-65,1.18,35,49),asym(85,78,1.36,46,30),asym(0,124,3.05,46,49)],mint,{color:ink,width:4.5});
 ellipse(seal,'soft belly',-5,61,102,101,pale);
 path(seal,'waving flipper',[asym(61,23,-.6,18,23),asym(109,-37,-1.4,32,24),asym(126,-41,1,15,12),asym(120,17,2.1,23,31),asym(74,58,-2.3,26,21)],mint,{color:ink,width:4});
 ellipse(seal,'left eye',-29,-48,15,20,ink);ellipse(seal,'right eye',31,-48,15,20,ink);
 ellipse(seal,'left glint',-31,-52,4,5,cream);ellipse(seal,'right glint',29,-52,4,5,cream);
 ellipse(seal,'left cheek',-47,-22,23,10,peach);ellipse(seal,'right cheek',48,-22,23,10,peach);
 ellipse(seal,'muzzle',1,-15,58,35,0xffedf2df);
 path(seal,'heart nose',[mirror(0,-24,0,8),asym(8,-20,1.7,4,3),straight(0,-13),asym(-8,-20,-1.7,3,4)],ink);
 path(seal,'little smile',[straight(-11,-8),asym(0,-3,0,4,4),straight(11,-8)],null,{color:ink,width:2.7},false);
 for(const [name,points]of [['left whisker top',[straight(-23,-16),straight(-63,-25)]],['left whisker low',[straight(-24,-8),straight(-62,-5)]],['right whisker top',[straight(25,-16),straight(65,-25)]],['right whisker low',[straight(25,-8),straight(64,-5)]]])path(seal,name,points,null,{color:ink,width:2.5},false);
 // A small coral shell and two sea-glass pebbles complete the shore.
 const shell=group('shore treasures',132,427);
 path(shell,'coral shell',[straight(-19,6),asym(-23,-9,-1.3,8,8),mirror(0,-23,0,12),asym(23,-9,1.3,8,8),straight(19,6)],peach,{color:0xff986e57,width:2.5});
 for(const x of [-10,0,10])path(shell,'shell ridge '+x,[straight(0,5),straight(x,-15)],null,{color:0xffbc8565,width:2},false);
 ellipse(root,'mint pebble',362,448,23,11,pale);ellipse(root,'cream pebble',387,438,12,8,cream);
 const records=[{type:'Backboard',fields:{}},{type:'Artboard',fields:{name:'Tide — a shore-side hello',width:512,height:512}}],ids=new Map();
 const emit=(type,fields)=>{records.push({type,fields});return records.length-2;};
 const walk=(list,parentId)=>{for(const n of [...list].reverse()){
  const id=emit(n.type,{name:n.name,parentId,...n.fields});ids.set(n.name,id);
  if(n.children){walk(n.children,id);continue;}
  const contour=emit(n.contour.type,{parentId:id,...n.contour.fields});
  for(const v of n.vertices)emit(v.type,{parentId:contour,...v.fields});
  if(n.fill!==null){const paint=emit('Fill',{parentId:id});emit('SolidColor',{parentId:paint,colorValue:n.fill});}
  if(n.stroke){const paint=emit('Stroke',{parentId:id,thickness:n.stroke.width,cap:1,join:1});emit('SolidColor',{parentId:paint,colorValue:n.stroke.color});}
 }};walk(root,0);
 emit('LinearAnimation',{name:'Shore hello',fps:60,duration:120,loopValue:1});
 for(const [name,property,keys]of [['Pebble',14,[[0,282],[60,277],[120,282]]],['waving flipper',15,[[0,0],[30,-.12],[60,.04],[90,-.12],[120,0]]]]){
  emit('KeyedObject',{objectId:ids.get(name)});emit('KeyedProperty',{propertyKey:property});for(const [frame,value]of keys)emit('KeyFrameDouble',{frame,value,interpolationType:1});
 }
 return records;
}
